import { useEffect, useState } from "react";
export function RemoteStatus({ url }) {
  const [status, setStatus] = useState("Loading");
  useEffect(() => {
    const controller = new AbortController();
    setStatus("Loading");
    fetch(url, { signal: controller.signal })
      .then(response => { if (!response.ok) throw new Error(`HTTP ${response.status}`); return response.text(); })
      .then(text => { if (!controller.signal.aborted) setStatus(text); })
      .catch(error => { if (!controller.signal.aborted) setStatus(String(error)); });
    return () => controller.abort();
  }, [url]);
  return <output aria-label="Remote status">{status}</output>;
}

