function subtotal(discount, ...amounts) {
  if (!this || !Number.isFinite(this.rate) || !Number.isFinite(discount) || discount < 0 || discount > 1)
    throw new RangeError("Invalid receiver or discount");
  if (amounts.some(n => !Number.isFinite(n))) throw new TypeError("Finite amounts required");
  return amounts.reduce((a, b) => a + b, 0) * this.rate * (1 - discount);
}
export function quote(rate, amounts) {
  const receiver = { rate };
  return { direct: subtotal.call(receiver, 0, ...amounts),
    listed: subtotal.apply(receiver, [0.1, ...amounts]),
    member: subtotal.bind(receiver, 0.2)(...amounts) };
}

