export function* batches(items, size = 2) {
  if (!Number.isInteger(size) || size < 1) throw new RangeError("Positive batch size required");
  let batch = [];
  for (const item of items) {
    batch.push(item);
    if (batch.length === size) { yield batch; batch = []; }
  }
  if (batch.length) yield batch;
}

export function* nonblankLines(source) {
