export function microtaskBatch(flush, onError) {
  let queued = false;
  return () => {
    if (queued) return;
    queued = true;
    queueMicrotask(() => {
      queued = false;
      try { flush(); } catch (error) { onError(error); }
    });
  };
}

export function abortableDelay(ms, signal) {
  return new Promise((resolve, reject) => {
    if (!Number.isFinite(ms) || ms < 0 || ms > 2147483647) { reject(new RangeError("Invalid delay")); return; }
    if (signal.aborted) { reject(signal.reason); return; }
    const cleanup = () => { clearTimeout(timer); signal.removeEventListener("abort", abort); };
    const abort = () => { cleanup(); reject(signal.reason); };
    const timer = setTimeout(() => { cleanup(); resolve("elapsed"); }, ms);
    signal.addEventListener("abort", abort, { once: true });
  });
}

export async function deadlineJson(url, ms, fetcher = fetch) {
  if (!Number.isFinite(ms) || ms < 0 || ms > 2147483647) throw new RangeError("Invalid deadline");
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(new Error("Deadline exceeded")), ms);
  try {
    const response = await fetcher(url, { signal: controller.signal });
    if (!response.ok) throw new Error("HTTP " + response.status);
    return await response.json();
  } finally { clearTimeout(timer); }
}

