export function fixturePath(root, name) {
  if (typeof name !== "string" || !name || isAbsolute(name)) throw new TypeError("Relative filename required");
  const base = resolve(root);
  const candidate = resolve(base, name);
  const within = relative(base, candidate);
  if (!within || within === ".." || within.startsWith(".." + sep) || isAbsolute(within))
    throw new RangeError("Path escapes fixture root");
  return candidate;
}

