export function delegateRemove(list, remove) {
  const click = event => {
    const target = event.target;
    if (!(target instanceof list.ownerDocument.defaultView.Element)) return;
    const button = target.closest("button[data-id]");
    if (!button || !list.contains(button) || button.disabled) return;
    remove(button.dataset.id);
  };
  list.addEventListener("click", click);
  return () => list.removeEventListener("click", click);
}

export function delegateTabs(tablist) {
  const click = event => {
    const target = event.target;
    if (!(target instanceof tablist.ownerDocument.defaultView.Element)) return;
    const tab = target.closest("[role=tab]");
    if (!tab || !tablist.contains(tab) || tab.getAttribute("aria-disabled") === "true") return;
    for (const item of tablist.querySelectorAll("[role=tab]")) {
      item.setAttribute("aria-selected", String(item === tab)); item.tabIndex = item === tab ? 0 : -1;
    }
    tab.focus();
  };
  tablist.addEventListener("click", click);
  return () => tablist.removeEventListener("click", click);
}

