import { test, expect, vi } from "vitest";
function debounce(callback, ms) {
  let timer;
  const schedule = value => { clearTimeout(timer); timer = setTimeout(() => callback(value), ms); };
  schedule.cancel = () => clearTimeout(timer);
  return schedule;
}
test("debounce keeps the latest value and supports cancellation", async () => {
  vi.useFakeTimers();
  try {
    const callback = vi.fn(); const schedule = debounce(callback, 20);
    schedule("old"); schedule("new");
    await vi.advanceTimersByTimeAsync(19); expect(callback).not.toHaveBeenCalled();
    await vi.advanceTimersByTimeAsync(1); expect(callback).toHaveBeenCalledExactlyOnceWith("new");
