export function indexRecords(records) {
  const index = new Map();
  for (const record of records) {
    if (index.has(record.id)) throw new Error("Duplicate id");
    index.set(record.id, record);
  }
  return index;
}

import { readFile } from "node:fs/promises";
export async function readSettings(url) {
  const settings = JSON.parse(await readFile(url, "utf8"));
  if (!settings || Array.isArray(settings) || typeof settings.enabled !== "boolean") throw new TypeError("Boolean enabled required");
  return { enabled: settings.enabled };
}
